globalThis.UUID={make(){const n=globalThis.crypto;if("function"==typeof n?.randomUUID)return n.randomUUID();if("function"!=typeof n?.getRandomValues)throw new Error("Cryptographic random generation is unavailable");const o=n.getRandomValues(new Uint8Array(16));o[6]=15&o[6]|64,o[8]=63&o[8]|128;const t=[...o].map(n=>n.toString(16).padStart(2,"0")).join("");return`${t.slice(0,8)}-${t.slice(8,12)}-${t.slice(12,16)}-${t.slice(16,20)}-${t.slice(20)}`}};
